#!/usr/bin/env python3
"""Filter and aggregate RFC-4180 CSV files."""

import argparse
import csv
import json
import sys
from collections import defaultdict
from decimal import Decimal, InvalidOperation


def fail(message):
    raise ValueError(message)


def parse_filter(value):
    if "=" not in value:
        fail("malformed filter {!r}; expected COLUMN=VALUE".format(value))
    column, expected = value.split("=", 1)
    if not column:
        fail("malformed filter {!r}; column cannot be empty".format(value))
    return column, expected


def read_csv(path):
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source)
            try:
                headers = next(reader)
            except StopIteration:
                fail("input CSV is empty")
            if not headers or any(not header for header in headers):
                fail("CSV headers must be non-empty")
            if len(set(headers)) != len(headers):
                fail("CSV headers must be unique")

            rows = []
            for row_number, row in enumerate(reader, start=2):
                if len(row) != len(headers):
                    fail(
                        "row {} has {} fields; expected {}".format(
                            row_number, len(row), len(headers)
                        )
                    )
                rows.append((row_number, dict(zip(headers, row))))
            return headers, rows
    except OSError as error:
        fail("cannot read {!r}: {}".format(path, error))
    except csv.Error as error:
        fail("malformed CSV: {}".format(error))


def decimal_string(value):
    if value == 0:
        return "0"
    rendered = format(value.normalize(), "f")
    return rendered.rstrip("0").rstrip(".") if "." in rendered else rendered


def aggregate(rows, group_by, sum_column, avg_column):
    groups = defaultdict(list)
    for row_number, row in rows:
        groups[row[group_by]].append((row_number, row))

    result = []
    for group_value in sorted(groups):
        group_rows = groups[group_value]
        output = {group_by: group_value}
        for operation, column in (("sum", sum_column), ("avg", avg_column)):
            if column is None:
                continue
            values = []
            for row_number, row in group_rows:
                try:
                    value = Decimal(row[column])
                except (InvalidOperation, ValueError):
                    fail("invalid numeric value at row {}, column {!r}".format(row_number, column))
                if not row[column] or not value.is_finite():
                    fail("invalid numeric value at row {}, column {!r}".format(row_number, column))
                values.append(value)
            total = sum(values, Decimal("0"))
            value = total if operation == "sum" else total / Decimal(len(values))
            output["{}_{}".format(operation, column)] = decimal_string(value)
        result.append(output)
    return result


def emit(rows, headers, output_format):
    if output_format == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False)
        sys.stdout.write("\n")
        return
    writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", metavar="INPUT.csv")
    parser.add_argument("--where", action="append", default=[], metavar="COLUMN=VALUE")
    parser.add_argument("--group-by", metavar="COLUMN")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN")
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)

    try:
        headers, numbered_rows = read_csv(args.input)
        filters = [parse_filter(value) for value in args.where]
        requested = [column for column, _ in filters]
        requested += [column for column in (args.group_by, args.sum_column, args.avg_column) if column]
        unknown = next((column for column in requested if column not in headers), None)
        if unknown is not None:
            fail("unknown column {!r}".format(unknown))
        if (args.sum_column or args.avg_column) and not args.group_by:
            fail("--sum and --avg require --group-by")

        filtered = [
            (row_number, row)
            for row_number, row in numbered_rows
            if all(row[column] == expected for column, expected in filters)
        ]
        if args.sum_column or args.avg_column:
            result = aggregate(filtered, args.group_by, args.sum_column, args.avg_column)
            output_headers = [args.group_by]
            output_headers += [
                "{}_{}".format(operation, column)
                for operation, column in (("sum", args.sum_column), ("avg", args.avg_column))
                if column is not None
            ]
        else:
            result = [row for _, row in filtered]
            output_headers = headers
        emit(result, output_headers, args.output)
    except ValueError as error:
        parser.exit(2, "error: {}\n".format(error))


if __name__ == "__main__":
    main()

